  summary = 'The recommended syllabus preserves the standard managerial accounting foundation while adding advanced decision, control, analytics, ESG, and executive communication topics. It distinguishes internal decision support from external reporting and frames the controller/CMA role.',
  data = $maccjson${"slug": "managerial-accounting", "title": "Managerial Accounting", "description": "The recommended syllabus preserves the standard managerial accounting foundation while adding advanced decision, control, analytics, ESG, and executive communication topics. It distinguishes internal decision support from external reporting and frames the controller/CMA role.", "topics": [{"id": "e38a42ee-17f9-4978-98fb-5d1587f9347a", "type": "topic", "title": "Managerial Accounting Purpose, Ethics, and Decision Context", "description": "Distinguishes internal decision support from external reporting and frames the controller/CMA role.", "children": [{"id": "7136ae68-5601-4256-81fd-b50ff4a6778c", "type": "subtopic", "title": "Internal Versus External Accounting", "children": [{"id": "8ce5e157-e053-4b28-b569-fab8d3d028a4", "type": "concept", "title": "Financial accounting versus managerial accounting"}, {"id": "6ae8a1f7-cef9-46de-8215-ee7994e5ad65", "type": "concept", "title": "Internal users and decision relevance"}, {"id": "c8473202-a9f0-409e-ae89-086fc6346b72", "type": "concept", "title": "Timeliness versus precision"}, {"id": "5761340d-6011-4cfe-8e22-2b742255c6ff", "type": "concept", "title": "Confidential information and competitive sensitivity"}, {"id": "3082fa41-c31f-4a67-a35b-8e3ad0dec5a0", "type": "concept", "title": "Planning, directing, controlling, and improving"}], "description": "Students learn why managerial accounting is built for planning, control, and decisions rather than public reporting compliance."}, {"id": "5e8dcabf-0bad-49b8-aeca-21220defeb90", "type": "subtopic", "title": "Ethics and Professional Judgment", "children": [{"id": "24fd418d-5076-4a09-bcac-773536aa7fbd", "type": "concept", "title": "IMA Statement of Ethical Professional Practice"}, {"id": "a4cebbbb-1616-4ce3-9851-0d0110258826", "type": "concept", "title": "Confidentiality and conflicts of interest"}, {"id": "b2e12eda-b155-42a1-b320-c8117047ac16", "type": "concept", "title": "Budgetary slack and pressure to manipulate targets"}, {"id": "8629a7d5-d889-47d8-b7fb-7f31bca362e5", "type": "concept", "title": "Relevant range assumptions and disclosure"}, {"id": "5f26605c-0a5e-446f-b759-16db19b177da", "type": "concept", "title": "Controller responsibilities and escalation"}], "description": "The topic frames accounting information as a governance tool where integrity, objectivity, and competence shape decisions."}, {"id": "bc41447a-15b5-4ba8-8a32-4b5657408562", "type": "subtopic", "title": "Decision Models and Information Quality", "children": [{"id": "1ef8bee9-8284-4d81-b871-480b2da3729e", "type": "concept", "title": "Decision alternatives"}, {"id": "5c1bbe63-83e9-4d23-b355-24b9777d4f91", "type": "concept", "title": "Relevant information"}, {"id": "d3be6705-599f-44a8-9a81-59111838a17b", "type": "concept", "title": "Sunk costs and opportunity costs"}, {"id": "3747548f-034f-4f4c-b947-0bf74f15e005", "type": "concept", "title": "Quantitative and qualitative factors"}, {"id": "001acb5c-9bd4-49e9-9067-eb2f79de5ac2", "type": "concept", "title": "Sensitivity analysis and uncertainty"}], "description": "Students connect accounting data to managerial choices, recognizing that good numbers still require context and judgment."}]}, {"id": "f0948f80-62c0-455d-8ee0-b762de66f832", "type": "topic", "title": "Cost Terms, Cost Behavior, and Cost Classification", "description": "Builds the vocabulary for tracing, assigning, predicting, and managing costs.", "children": [{"id": "f45f7997-670d-4c73-b81c-bb6951949916", "type": "subtopic", "title": "Cost Object and Traceability", "children": [{"id": "6cfbf467-5092-45e3-b2ea-2d16a0458dd9", "type": "concept", "title": "Direct costs"}, {"id": "27726958-004e-41b3-b293-5769da83a9da", "type": "concept", "title": "Indirect costs"}, {"id": "b44e6b25-a34d-4b04-95ec-aaf2dcf602b6", "type": "concept", "title": "Cost tracing"}, {"id": "00fe1070-37cd-4fcb-ae8b-eeb72226da75", "type": "concept", "title": "Cost allocation"}, {"id": "f99a3