ng"}, {"id": "681315cc-ec7f-4590-92d2-393c0d8c0ffe", "type": "concept", "title": "Fixed manufacturing overhead"}, {"id": "125a2656-4e6a-482b-884b-db0d3826b908", "type": "concept", "title": "Contribution margin income statement"}, {"id": "8e6ecdb5-8cff-4bd9-9223-4be79b6cddd1", "type": "concept", "title": "Gross margin format"}], "description": "Students compare internal contribution formats with absorption costing required for external reporting."}, {"id": "d92d97d2-dbb9-4977-8286-e0e5828ce791", "type": "subtopic", "title": "Inventory and Income Effects", "children": [{"id": "f9f3f4db-c953-4b99-8f61-bc424e51c4f2", "type": "concept", "title": "Units produced versus units sold"}, {"id": "bb439d00-6574-4fd5-9e6d-e233a6b098e0", "type": "concept", "title": "Fixed overhead deferred in inventory"}, {"id": "f13222ff-cc16-4316-b660-cb7961cdc3ce", "type": "concept", "title": "Inventory build"}, {"id": "2be8ec44-2607-4350-8871-a307d3fca77f", "type": "concept", "title": "Inventory drawdown"}, {"id": "4918249b-0c3d-4fe1-b3b4-7607ab1a1955", "type": "concept", "title": "Reconciliation of income differences"}], "description": "This shows how production volume can influence reported income under absorption costing."}, {"id": "dab59f48-d797-48e3-83c5-b56a857124fc", "type": "subtopic", "title": "Managerial Use and Misuse", "children": [{"id": "762307e1-e980-4707-9df6-770b952f15e3", "type": "concept", "title": "Throughput emphasis"}, {"id": "7aad6cc9-52a7-4af7-9394-681c1cf18f8d", "type": "concept", "title": "Overproduction incentives"}, {"id": "56cf8d8b-bb50-49dd-94ea-84731720538d", "type": "concept", "title": "Capacity utilization"}, {"id": "eac2657c-c876-4dd3-90f2-876f2c0ff933", "type": "concept", "title": "Internal reporting policy"}, {"id": "e58cce02-6a09-4a09-9a01-4d7d73e55fef", "type": "concept", "title": "Performance evaluation safeguards"}], "description": "Students evaluate when each method supports decisions and when incentives may distort production choices."}]}, {"id": "e83dc007-330d-4988-8e57-5c68f7fdb505", "type": "topic", "title": "Master Budgets, Operating Budgets, and Financial Planning", "description": "Develops the integrated planning system linking sales, operations, cash, and pro forma statements.", "children": [{"id": "e90bd169-3cd4-48f0-9b12-0ee4c57fde22", "type": "subtopic", "title": "Operating Budget Sequence", "children": [{"id": "09e9544f-1ff5-49f9-9736-a86af3e3a7c8", "type": "concept", "title": "Sales budget"}, {"id": "b84ffd10-a321-4ab7-8c01-d45d223ca37a", "type": "concept", "title": "Production budget"}, {"id": "02d2844e-a846-469f-967b-e830d712475c", "type": "concept", "title": "Direct materials budget"}, {"id": "6e468fb4-1f4e-45c1-b78e-703f96bf767a", "type": "concept", "title": "Direct labor budget"}, {"id": "a124282f-ab94-4fd8-9e0e-b2310b1f44c6", "type": "concept", "title": "Manufacturing overhead budget"}], "description": "Students learn how a master budget translates strategy into coordinated operating plans."}, {"id": "cb5a39bf-9ab3-43f5-a0be-76c2b6702928", "type": "subtopic", "title": "Financial Budgets", "children": [{"id": "8aaf82e5-c537-478b-9459-fbfdc4854327", "type": "concept", "title": "Cash budget"}, {"id": "2a594451-636c-4d46-a54b-2c6a6c4d40da", "type": "concept", "title": "Budgeted income statement"}, {"id": "97955158-ec12-4911-880d-df53ef338bf7", "type": "concept", "title": "Budgeted balance sheet"}, {"id": "910a7a61-48fd-46f4-b32e-e7ad7345bbd2", "type": "concept", "title": "Capital expenditures budget"}, {"id": "f4e70c59-8dda-4447-a847-79c31c29b776", "type": "concept", "title": "Financing needs"}], "description": "This connects operating plans to cash, financing, and projected financial statements."}, {"id": "e797fe37-9e9d-4131-aad3-8e5cb643409d", "type": "subtopic", "title": "Planning Process and Governance", "children": [{"id": "7497e34f-087e-482f-b7e1-9d778ec2471a", "type": "concept", "title": "Participative budgeting"}, {"id": "67a25268-0d2f-4fe5-96d9-b62245ec0f10", "type": "concept", "title": "Top-down versus bottom-up budgeting"}, {"id": "7b86e4a6-3d56-461d-9993-152b4ce126e2", "type": "concept", "title": "Budget calendar"}, {"id": "69fbf9cc-0caa-4269-b9b3-1f9643913598", "type": "concept", "title": "Assumption documentation"}, {"id": "837723c9-ae49-4c99-935d-7a9516d1d936", "type": "concept", "title": "Budget review meetings"}], "description": "Students study the people, assumptions, and controls that make budgets useful."}]}, {"id": "db19dc49-80f6-4991-85c8-5d4c34bcef24", "type": "topic", "title": "Flexible Budgets, Standard Costs, and Variance Analysis", "description": "Separates volume effects from operating performance and diagnoses price, efficiency, mix, and yield drivers.", "children": [{"id": "7bc9c2bb-ed0a-4e49-864b-bc26f8281b0d", "type": "subtopic", "title": "Flexible Budget Logic", "children": [{"id": "3e5cfb33-9419-4fd8-9374-bf65de29d4ee", "type": "concept", "title": "Static budget"}, {"id": "9a4aacd0-6193-46cf-b63c-52b5c5b37147", "type": "concept", "title": "Flexible budget"}, {"id": "a436692a-22f7-4329-8870-77ece796c8ae", "type": "concept", "title": "Activity variance"}, {"id": "0b917282-7b0e-4bf2-bc06-f2ff660eac8f", "type": "concept", "title": "Revenue variance"}, {"id": "0c5b0381-4e37-47d5-b09b-6abb42b13aeb", "type": "concept", "title": "Spending variance"}], "description": "Students learn to compare actual results against what costs should have been at actual activity levels."}, {"id": "aec00ff3-b7d6-4fc1-a053-a65db739fdec", "type": "subtopic", "title": "Direct Cost Variances", "children": [{"id": "880e94fa-431a-4c61-8278-f72996e35089", "type": "concept", "title": "Materials price variance"}, {"id": "f1f491e9-a606-4bef-80a5-239e317ac87e", "type": "concept", "title": "Materials quantity variance"}, {"id": "7ccd5fbd-0dbd-4509-88b0-34f094925f28", "type": "concept", "title": "Labor rate variance"}, {"id": "f6bdd2de-69f4-4f16-a9cd-b57e016f12b9", "type": "concept", "title": "Labor efficiency variance"}, {"id": "7b05c775-924b-47c1-909f-c27b3fbc7082", "type": "concept", "title": "Purchasing and production responsibility"}], "description": "This builds diagnostic skill for materials and labor performance."}, {"id": "f38fc151-fee0-4ca6-b6a6-ef198d3f944c", "type": "subtopic", "title": "Overhead and Advanced Variances", "children": [{"id": "c193973c-c2cb-4eff-a7c7-5310c87d3411", "type": "concept", "title": "Variable overhead spending variance"}, {"id": "400de64f-a70f-41db-bf5a-8b26c53c478e", "type": "concept", "title": "Variable overhead efficiency variance"}, {"id": "73d0861b-333b-4534-8564-39205592e02f", "type": "concept", "title": "Fixed overhead budget variance"}, {"id": "7b2b1f47-f472-4100-a6dc-74d669ca5dc1", "type": "concept", "title": "Fixed overhead volume variance"}, {"id": "0ad0186c-afe4-45e6-bb2b-79e9505343f1", "type": "concept", "title": "Mix and yield variances"}], "description": "Students analyze fixed and variable overhead plus mix/yield effects in more complex operations."}]}, {"id": "215637ac-af41-405c-b1ad-6ea323d1ded0", "type": "topic", "title": "Relevant Costs, Short-Term Decisions, and Constraint Analysis", "description": "Applies differential analysis to pricing, outsourcing, special orders, product mix, and scarce resources.", "children": [{"id": "aac5505c-b642-44e9-8242-0163a22e6066", "type": "subtopic", "title": "Differential Decision Analysis", "children": [{"id": "79b8ed21-e0a5-4a01-a018-1d2b0da884f6", "type": "concept", "title": "Avoidable costs"}, {"id": "144218ef-6143-483b-b476-6f9f12a211c2", "type": "concept", "title": "Unavoidable costs"}, {"id": "c8de8d9a-3dfb-4170-a8e9-c361c9ddafdd", "type": "concept", "title": "Incremental revenue"}, {"id": "52ede43a-2e2b-441b-b064-65a2013a1c1b", "type": "concept", "title": "Opportunity cost"}, {"id": "0ffead6e-a33c-4d35-9604-49de8829e517", "type": "concept", "title": "Qualitative constraints"}], "description": "Students learn to isolate the costs and benefits that change across alternatives."}, {"id": "d0cdae34-07ec-473b-90c1-567da4acaf5e", "typ